import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = { stripeSecretKey: 'sk_test_123', fetch }
    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotContactPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.stripeCustomerId).toBe('cus_NffrFeUfNV2Hib')
  })
})

describe('handle', () => {
  it('creates a Stripe customer with mapped fields on happy path', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://api.stripe.com/v1/customers')
      expect(req.headers.get('authorization')).toBe('Bearer sk_test_123')
      const body = new URLSearchParams(req.body as string)
      expect(body.get('email')).toBe('jane.doe@example.com')
      expect(body.get('name')).toBe('Jane Doe')
      return jsonResponse(TARGET_ENDPOINTS[0].response, 200)
    })

    const payload: HubSpotContactPayload = {
      email: 'jane.doe@example.com',
      firstname: 'Jane',
      lastname: 'Doe',
      lifecyclestage: 'customer'
    }
    const config: ConnectorConfig = { stripeSecretKey: 'sk_test_123', fetch }
    const result = await handle(payload, config)

    expect(result.stripeCustomerId).toBe('cus_NffrFeUfNV2Hib')
    expect(calls.length).toBe(1)
  })

  it('throws when email is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = {
      firstname: 'Jane',
      lastname: 'Doe',
      lifecyclestage: 'customer'
    } as unknown as HubSpotContactPayload
    const config: ConnectorConfig = { stripeSecretKey: 'sk_test_123', fetch }

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: email')
  })

  it('throws when firstname is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = {
      email: 'jane.doe@example.com',
      lastname: 'Doe',
      lifecyclestage: 'customer'
    } as unknown as HubSpotContactPayload
    const config: ConnectorConfig = { stripeSecretKey: 'sk_test_123', fetch }

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: firstname')
  })

  it('throws when lastname is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = {
      email: 'jane.doe@example.com',
      firstname: 'Jane',
      lifecyclestage: 'customer'
    } as unknown as HubSpotContactPayload
    const config: ConnectorConfig = { stripeSecretKey: 'sk_test_123', fetch }

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: lastname')
  })

  it('throws when lifecyclestage is not customer', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload: HubSpotContactPayload = {
      email: 'jane.doe@example.com',
      firstname: 'Jane',
      lastname: 'Doe',
      lifecyclestage: 'lead'
    }
    const config: ConnectorConfig = { stripeSecretKey: 'sk_test_123', fetch }

    await expect(handle(payload, config)).rejects.toThrow("Invalid lifecyclestage: expected 'customer', got 'lead'")
  })

  it('throws on non-2xx response from Stripe', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Invalid email' }, 400))
    const payload: HubSpotContactPayload = {
      email: 'invalid-email',
      firstname: 'Jane',
      lastname: 'Doe',
      lifecyclestage: 'customer'
    }
    const config: ConnectorConfig = { stripeSecretKey: 'sk_test_123', fetch }

    await expect(handle(payload, config)).rejects.toThrow('Stripe API error: 400 Bad Request at POST https://api.stripe.com/v1/customers')
    expect(calls.length).toBe(1)
  })

  it('uses injected fetch and sends correct auth header', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse(TARGET_ENDPOINTS[0].response, 200))
    const payload: HubSpotContactPayload = {
      email: 'test@example.com',
      firstname: 'Test',
      lastname: 'User',
      lifecyclestage: 'customer'
    }
    const config: ConnectorConfig = { stripeSecretKey: 'sk_live_abc', fetch }

    await handle(payload, config)

    expect(calls[0].headers.get('authorization')).toBe('Bearer sk_live_abc')
    expect(calls[0].method).toBe('POST')
    expect(calls[0].url).toBe('https://api.stripe.com/v1/customers')
  })
})

